<?php $this->layout('default'); use Moves\Services\CmsAuth; use Moves\Services\PlatformBilling as B; use Moves\Support\CmsView as V; $rows = B::plans(['q' => V::queryString('q')]);
if (CmsAuth::can($admin, 'plans.manage')) { $this->start('actions'); ?><a class="cms-btn-primary" href="/planos/novo"><?= V::icon('plus') ?>Novo plano</a><?php $this->stop(); } ?>
<?= V::kpis([['tag', 'Planos', (string) count($rows), 'cadastrados'], ['check', 'Ativos', (string) count(array_filter($rows, static fn ($p) => $p['status'] === 'active')), 'disponíveis'], ['globe', 'No site', (string) count(array_filter($rows, static fn ($p) => $p['is_public'] && $p['status'] === 'active')), 'visíveis ao público'], ['users', 'Assinantes', (string) array_sum(array_column($rows, 'subscribers')), 'contratos vigentes']]) ?>
<section class="cms-list"><?= V::listHead('Lista de planos', count($rows) . ' registro(s)', V::searchForm('Buscar plano')) ?>
<?php if ($rows === []): ?><?= V::empty('Nenhum plano cadastrado.', 'O site só mostra planos ativos, públicos e com preço.') ?><?php else: ?><div class="cms-table-wrap" tabindex="0" role="region" aria-label="Planos"><table><thead><tr><th>Plano</th><th class="num">Mensal</th><th class="num">Anual</th><th>Status</th><th>Site</th><th class="num">Assinantes</th><th class="cms-th-actions">Ações</th></tr></thead><tbody><?php foreach ($rows as $p): ?><tr><td><div class="cms-cell"><i class="cms-thumb"><?= V::icon('tag') ?></i><div><a href="/planos/<?= (int) $p['id'] ?>"><?= V::e($p['name']) ?></a><?= $p['is_featured'] ? ' ' . V::badge('active', 'Destaque') : '' ?><br><code class="cms-chip"><?= V::e($p['plan_key']) ?></code></div></div></td><td class="num"><?= V::money($p['monthly_price']) ?></td><td class="num"><?= V::money($p['annual_price']) ?></td><td><?= V::badge($p['status'], $p['status'] === 'active' ? 'Ativo' : 'Inativo') ?></td><td><?= $p['is_public'] ? 'Público' : 'Oculto' ?></td><td class="num"><?= (int) $p['subscribers'] ?></td><td class="cms-td-actions"><?= V::iconLink('/planos/' . (int) $p['id'], 'Editar') ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
